#!/usr/bin/env node
/**
 * W63b evaluation runner. Runs the REAL OCR and temporal producers through the product path (admission -> worker -> sealed envelope ->
 * W63a server perception snapshot) on a corpus generated by w63b-generate-corpus.mjs, in the supervised throwaway PostgreSQL, and
 * compares the snapshot with the independent labels using the frozen metrics and thresholds.
 *
 *   node --experimental-transform-types --disable-warning=MODULE_TYPELESS_PACKAGE_JSON scripts/validation/w63b-evaluate.mjs \
 *     --split development|evaluation --corpus <dir> --out <dir> [--only id,id] [--phase all|main|robustness] [--no-freeze-check]
 *
 * It refuses to run when the thresholds, metrics, spec, generator, pre-registration or corpus manifest differ from
 * docs/quality/w63b-freeze.json (`--no-freeze-check` exists for the development split only), and it never edits an oracle or a threshold.
 */
import { execFile } from 'node:child_process'
import { createHash, randomUUID } from 'node:crypto'
import { copyFile, mkdir, mkdtemp, readFile, rm, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { promisify } from 'node:util'

import { PrismaClient } from '../../generated/prisma-v2/index.js'
import { commitSealedChild, planPlayingRecordings } from '../../tests/v2/helpers/pg-output-world.mjs'
import { seedPerceptionProducerContext } from '../../tests/v2/helpers/perception-producer-pg-world.mjs'
import { aggregateOcr, aggregateTemporal, evaluateClaims, evaluateOcr, evaluateOcrClock, evaluateTemporal, judge } from './w63b-metrics.mjs'
import { OCR_SAMPLE_INTERVAL_FRAMES } from './w63b-corpus-spec.mjs'
import { STRATA } from './w63b-thresholds.mjs'

const { createExternalAuditContext } = await import('../../src/v2/application/authenticate-api-client.ts')
const { enqueuePerceptionProducerRunService } = await import('../../src/v2/application/enqueue-perception-producer-run.ts')
const { enqueueTemporalProducerRunService } = await import('../../src/v2/application/enqueue-temporal-producer-run.ts')
const { readServerPerceptionSnapshotService } = await import('../../src/v2/application/server-perception-snapshots.ts')
const { assembleServerPerceptionSnapshot } = await import('../../src/v2/domain/server-perception-snapshot.ts')
const { createPerceptionProducerWorker, createTemporalProducerWorker } = await import('../../src/v2/infrastructure/repository-factory.ts')
const { disconnectV2PostgresClient } = await import('../../src/v2/infrastructure/prisma-postgres/client.ts')
const { PrismaPerceptionProducerRequestContextRepository, PrismaTemporalProducerRequestContextRepository } = await import('../../src/v2/infrastructure/prisma/perception-producer-request-context-repository.ts')
const { PrismaPublicOperationRepository } = await import('../../src/v2/infrastructure/prisma/public-operation-repository.ts')
const { PrismaServerPerceptionEvidenceReader } = await import('../../src/v2/infrastructure/prisma/server-perception-evidence-reader.ts')
const { PrismaServerPerceptionSnapshotRepository } = await import('../../src/v2/infrastructure/prisma/server-perception-snapshot-repository.ts')

const exec = promisify(execFile)
const root = fileURLToPath(new URL('../..', import.meta.url))
const argument = (name, fallback) => { const index = process.argv.indexOf(`--${name}`); return index >= 0 ? process.argv[index + 1] : fallback }
const sha256 = (bytes) => createHash('sha256').update(bytes).digest('hex')
const fileSha = async (path) => sha256(await readFile(path))
const stable = (value) => JSON.stringify(value, null, 2)

// ------------------------------------------------------------------------------------------------------------ preconditions

async function git(...args) { return (await exec('git', args, { cwd: root, windowsHide: true })).stdout.trim() }

async function checkFreeze(split, corpusDir, manifestBytes) {
  const freezePath = join(root, 'docs/quality/w63b-freeze.json')
  const freeze = JSON.parse(await readFile(freezePath, 'utf8'))
  const problems = []
  for (const [file, expected] of Object.entries(freeze.files)) {
    const actual = await fileSha(join(root, file))
    if (actual !== expected) problems.push(`${file}: ${actual} != frozen ${expected}`)
  }
  const frozen = freeze.corpus[split]
  const manifestSha = sha256(manifestBytes)
  if (!frozen || frozen.manifestSha256 !== manifestSha) problems.push(`corpus manifest ${manifestSha} != frozen ${frozen?.manifestSha256}`)
  const dirty = await git('status', '--porcelain', '--', ...Object.keys(freeze.files), 'docs/quality/w63b-freeze.json')
  if (dirty) problems.push(`frozen paths have uncommitted changes:\n${dirty}`)
  const freezeCommit = await git('log', '-1', '--format=%H', '--', 'docs/quality/w63b-freeze.json')
  if (!freezeCommit) problems.push('docs/quality/w63b-freeze.json is not committed')
  return { problems, freezeCommit, freeze, manifestSha }
}

// ------------------------------------------------------------------------------------------------------------ one clip

function actorFor(world) {
  const auditContext = createExternalAuditContext({ clientId: world.clientId, credentialId: `w61-credential-${world.suffix}`,
    workspaceId: world.workspaceId, environment: 'production' })
  return { ...auditContext, scopes: new Set(['projects:write']), authenticationKind: 'bearer', clientKillSwitchEngaged: false,
    workspaceKillSwitchEngaged: false, clientAccessStatus: 'active', workspaceAccessStatus: 'active', auditContext }
}

function cutPlan(world, spec) {
  const play = planPlayingRecordings([world.recording])
  return (parent) => {
    const plan = play(parent)
    const clips = spec.editPlan.clips.map((clip) => ({ id: `w63b-${clip.id}`, sourceArtifactId: world.sourceId, sourceInFrame: clip.sourceInFrame,
      sourceOutFrame: clip.sourceOutFrame, timelineInFrame: clip.timelineInFrame, timelineOutFrame: clip.timelineOutFrame, rate: 1 }))
    return { ...plan, durationFrames: spec.editPlan.durationFrames, videoTracks: [{ ...plan.videoTracks[0], clips }] }
  }
}

async function prepareWorld(db, ctx, entry) {
  const world = await seedPerceptionProducerContext(db, { durationFrames: entry.spec.frames, sourceSha256: entry.sha256, byteSize: BigInt(entry.bytes) })
  const destination = join(ctx.artifactRoot, world.artifactKey)
  await mkdir(dirname(destination), { recursive: true })
  await copyFile(join(ctx.corpusDir, entry.file), destination)
  if (entry.spec.editPlan) {
    const head = await commitSealedChild(db, { workspaceId: world.workspaceId, projectId: world.projectId, actor: world.actor,
      suffix: `w63b-${world.suffix}-cut`, mutatePlan: cutPlan(world, entry.spec) })
    world.versionId = head.version.id
    world.editId = head.editPlanSnapshot.id
  }
  return world
}

function services(db, ctx) {
  const operations = new PrismaPublicOperationRepository(db)
  const createOperationId = () => `w63b-op-${randomUUID()}`
  return {
    operations,
    enqueueOcr: enqueuePerceptionProducerRunService({ context: new PrismaPerceptionProducerRequestContextRepository(db), operations, createOperationId }),
    enqueueTemporal: enqueueTemporalProducerRunService({ context: new PrismaTemporalProducerRequestContextRepository(db), operations, createOperationId }),
    snapshot: readServerPerceptionSnapshotService({ evidence: new PrismaServerPerceptionEvidenceReader(db),
      snapshots: new PrismaServerPerceptionSnapshotRepository(db), clock: () => new Date() }),
    evidence: new PrismaServerPerceptionEvidenceReader(db),
    runOcr: ctx.runOcr,
    runTemporal: ctx.runTemporal,
  }
}

async function produce(db, ctx, entry, world, { ocrInterval = OCR_SAMPLE_INTERVAL_FRAMES, label = 'main' } = {}) {
  const s = services(db, ctx)
  const actor = actorFor(world)
  const base = { workspaceId: world.workspaceId, projectId: world.projectId, projectVersionId: world.versionId, sourceArtifactId: world.sourceId, actor }
  const outcome = { ocr: null, temporal: null, operations: {} }
  const startedOcr = Date.now()
  const ocrQueued = await s.enqueueOcr({ ...base, sampleIntervalFrames: ocrInterval, idempotencyKey: `w63b-ocr-${label}-${world.suffix}` })
  outcome.operations.ocr = ocrQueued.operation.id
  outcome.ocr = { ...(await s.runOcr(`w63b-ocr-worker-${label}-${world.suffix}`)), seconds: (Date.now() - startedOcr) / 1000 }
  const startedTemporal = Date.now()
  const temporalQueued = await s.enqueueTemporal({ ...base, idempotencyKey: `w63b-temporal-${label}-${world.suffix}` })
  outcome.operations.temporal = temporalQueued.operation.id
  outcome.temporal = { ...(await s.runTemporal(`w63b-temporal-worker-${label}-${world.suffix}`)), seconds: (Date.now() - startedTemporal) / 1000 }
  for (const kind of ['ocr', 'temporal']) {
    const operation = await s.operations.findById(world.workspaceId, outcome.operations[kind])
    outcome[kind].operationStatus = operation?.operation.status ?? null
    outcome[kind].error = operation?.operation.error ?? null
  }
  return { services: s, outcome, actor, base }
}

function summarize(entry, produced, snapshot) {
  const evidence = { observations: snapshot?.result.observations ?? [], coverage: snapshot?.result.coverage ?? [] }
  const okOcr = produced.outcome.ocr.status === 'succeeded'
  const okTemporal = produced.outcome.temporal.status === 'succeeded'
  return {
    id: entry.id, stratum: entry.stratum, producers: { ocr: okOcr, temporal: okTemporal }, operations: produced.outcome,
    snapshotHash: snapshot?.snapshot.snapshotHash ?? null, snapshotId: snapshot?.id ?? null,
    rejected: snapshot?.snapshot.rejected ?? null, inputs: snapshot?.snapshot.inputs.map((input) => ({ kind: input.kind, envelopeId: input.envelopeId, envelopeHash: input.envelopeHash, observationCount: input.observationCount })) ?? [],
    coverage: evidence.coverage.map((item) => ({ kind: item.kind, state: item.state, observedMs: item.observedMs, reasonCode: item.reasonCode ?? null })),
    ocr: evaluateOcr(entry, evidence), temporal: evaluateTemporal(entry, evidence), claims: evaluateClaims(evidence), clock: evaluateOcrClock(entry, evidence),
  }
}

// ------------------------------------------------------------------------------------------------------------ strata

function aggregateStrata(reports) {
  const out = {}
  for (const [stratum, spec] of Object.entries(STRATA)) {
    const clips = reports.filter((report) => report.stratum === stratum)
    const needsOcr = ['ocr', 'combined', 'time-after-cuts'].includes(spec.kind)
    const needsTemporal = ['temporal', 'combined', 'time-after-cuts'].includes(spec.kind)
    const missing = clips.filter((clip) => (needsOcr && !clip.producers.ocr) || (needsTemporal && !clip.producers.temporal)).map((clip) => clip.id)
    const metrics = {
      ocr: aggregateOcr(clips.map((clip) => clip.ocr)), temporal: aggregateTemporal(clips.map((clip) => clip.temporal)),
      claims: { imageInsertClaimed: clips.some((clip) => clip.claims.imageInsertClaimed), reasonCodes: [...new Set(clips.map((clip) => clip.claims.imageInsertReasonCode))] },
      clock: clips.map((clip) => clip.clock),
    }
    const verdict = judge(stratum, metrics)
    const criteria = [...verdict.criteria, ...(Object.keys(spec.criteria).length ? [{ criterion: 'producersSucceededOnEveryClip', value: missing, rule: '== []', pass: missing.length === 0 }] : [])]
    const final = !clips.length ? 'unrun' : verdict.verdict === 'informational' ? 'informational' : criteria.every((item) => item.pass) ? 'pass' : 'fail'
    out[stratum] = { stratum, verdict: final, clips: clips.map((clip) => clip.id), criteria, missingEvidence: missing,
      metrics: { ocr: metrics.ocr.units ? metrics.ocr : null, temporal: metrics.temporal, claims: metrics.claims },
      failures: criteria.filter((item) => !item.pass).map((item) => `${item.criterion} ${item.rule}: ${JSON.stringify(item.value)}`) }
  }
  return out
}

// ------------------------------------------------------------------------------------------------------------ robustness

async function robustness(db, ctx, mainReports, producedByClip, entries) {
  const results = []
  const record = (id, contract, pass, evidence) => { results.push({ id, contract, pass, evidence }); console.log(JSON.stringify({ event: 'robustness', id, pass })) }
  const staticEntry = entries.find((entry) => entry.id === 'static-a')
  const base = producedByClip.get('static-a')
  if (staticEntry && base) {
    const { services: s, outcome, base: ask, actor } = base.produced
    const world = base.world
    // R1 duplicate: the same idempotency key replays the same operations, nothing is produced twice, the assembler lists the duplicate
    const again = await s.enqueueOcr({ ...ask, sampleIntervalFrames: OCR_SAMPLE_INTERVAL_FRAMES, idempotencyKey: `w63b-ocr-main-${world.suffix}` })
    const againTemporal = await s.enqueueTemporal({ ...ask, idempotencyKey: `w63b-temporal-main-${world.suffix}` })
    const idle = await s.runOcr(`w63b-ocr-worker-idle-${world.suffix}`)
    const idleTemporal = await s.runTemporal(`w63b-temporal-worker-idle-${world.suffix}`)
    const ocrRows = await db.v2PerceptionProducerEnvelope.count({ where: { workspaceId: world.workspaceId, operationId: outcome.operations.ocr } })
    const temporalRows = await db.v2TemporalProducerEnvelope.count({ where: { workspaceId: world.workspaceId, operationId: outcome.operations.temporal } })
    const input = await s.evidence.readForVersion({ workspaceId: world.workspaceId, projectId: world.projectId, projectVersionId: world.versionId, now: new Date() })
    const single = assembleServerPerceptionSnapshot(input)
    const doubled = assembleServerPerceptionSnapshot({ ...input, ocr: [...input.ocr, ...input.ocr], temporal: [...input.temporal, ...input.temporal] })
    const duplicateReasons = doubled.rejected.flatMap((item) => item.reasonCodes)
    record('duplicate-envelope', 'the same idempotency key replays the same operation; no second envelope; the assembler lists exactly one DUPLICATE_ENVELOPE per repeated envelope and keeps the timeline hash',
      again.operation.id === outcome.operations.ocr && againTemporal.operation.id === outcome.operations.temporal && idle === null && idleTemporal === null &&
        ocrRows === 1 && temporalRows === 1 && doubled.timelineHash === single.timelineHash && duplicateReasons.length === 2 && duplicateReasons.every((code) => code === 'DUPLICATE_ENVELOPE') && single.rejected.length === 0,
      { replayedOperationIds: [again.operation.id, againTemporal.operation.id], idleWorker: [idle, idleTemporal], envelopeRows: { ocr: ocrRows, temporal: temporalRows },
        timelineHashEqual: doubled.timelineHash === single.timelineHash, rejectedCodes: duplicateReasons, snapshotHashSingle: single.snapshotHash, snapshotHashDoubled: doubled.snapshotHash })

    // R2 gap: what no sample examined stays partial/absent with its complement stated, and nothing is complete by borrowing
    const snapshot = await s.snapshot({ workspaceId: world.workspaceId, projectId: world.projectId, projectVersionId: world.versionId })
    const byKind = Object.fromEntries(snapshot.result.coverage.map((item) => [item.kind, item]))
    const sampled = byKind.ocr.ranges.length
    const complement = byKind.ocr.unexaminedRanges.reduce((sum, range) => sum + (range[1] - range[0]), 0)
    record('gap-stays-partial', 'a range no sample examined stays unexamined: OCR partial with the exact complement, shot/motion partial (the last frame has no pair), image-insert/object/speaker/silence absent with their reasons',
      byKind.ocr.state === 'partial' && byKind.ocr.observedMs + complement === snapshot.result.range.endMs - snapshot.result.range.startMs &&
        byKind.shot.state === 'partial' && byKind.motion.state === 'partial' &&
        ['image-insert', 'object', 'speaker', 'silence'].every((kind) => byKind[kind].state === 'absent' && byKind[kind].reasonCode) &&
        !snapshot.result.coverage.some((item) => item.state === 'complete'),
      { states: Object.fromEntries(Object.entries(byKind).map(([kind, item]) => [kind, [item.state, item.reasonCode ?? null]])), ocrSampledRanges: sampled, ocrUnexaminedMs: complement })

    // R3 reorder (evidence order): evidence of ANOTHER version is rejected and listed; the order the evidence is handed over in changes nothing
    const otherKey = [...producedByClip.keys()].find((id) => id !== 'static-a' && id !== 'robustness-pts-gap-a' && producedByClip.get(id).produced.outcome.ocr.status === 'succeeded' && producedByClip.get(id).produced.outcome.temporal.status === 'succeeded')
    if (otherKey) {
      const otherWorld = producedByClip.get(otherKey).world
      const foreign = await s.evidence.readForVersion({ workspaceId: otherWorld.workspaceId, projectId: otherWorld.projectId, projectVersionId: otherWorld.versionId, now: new Date() })
      const own = await s.evidence.readForVersion({ workspaceId: world.workspaceId, projectId: world.projectId, projectVersionId: world.versionId, now: new Date() })
      const forward = assembleServerPerceptionSnapshot({ ...own, ocr: [...own.ocr, ...foreign.ocr], temporal: [...own.temporal, ...foreign.temporal] })
      const reversed = assembleServerPerceptionSnapshot({ ...own, ocr: [...foreign.ocr, ...own.ocr], temporal: [...foreign.temporal, ...own.temporal] })
      const alone = assembleServerPerceptionSnapshot(own)
      record('reordered-evidence-same-hash', 'the same evidence in another order is the same snapshot (same hash); evidence of another version is rejected and listed, never fused',
        forward.snapshotHash === reversed.snapshotHash && forward.rejected.length === 2 && forward.timelineHash === alone.timelineHash && alone.rejected.length === 0,
        { foreignClip: otherKey, forward: forward.snapshotHash, reversed: reversed.snapshotHash, rejected: forward.rejected.map((item) => [item.kind, item.reasonCodes]), timelineHashUnchanged: forward.timelineHash === alone.timelineHash })
    } else record('reordered-evidence-same-hash', 'evidence order does not change the snapshot', false, { reason: 'no second successful clip in this run to borrow foreign evidence from' })

    // R4 adversarial source (i): envelope rows bound to other source bytes are refused at read, and restoring them restores the read
    const temporalRow = await db.v2TemporalProducerEnvelope.findFirstOrThrow({ where: { workspaceId: world.workspaceId, operationId: outcome.operations.temporal } })
    const ocrRow = await db.v2PerceptionProducerEnvelope.findFirstOrThrow({ where: { workspaceId: world.workspaceId, operationId: outcome.operations.ocr } })
    const refusals = []
    await db.v2TemporalProducerEnvelope.update({ where: { id: temporalRow.id }, data: { sourceSha256: 'e'.repeat(64) } })
    try { await s.snapshot({ workspaceId: world.workspaceId, projectId: world.projectId, projectVersionId: world.versionId }); refusals.push(['temporal', 'served']) }
    catch (error) { refusals.push(['temporal', error?.code ?? String(error)]) }
    await db.v2TemporalProducerEnvelope.update({ where: { id: temporalRow.id }, data: { sourceSha256: temporalRow.sourceSha256 } })
    await db.v2PerceptionProducerEnvelope.update({ where: { id: ocrRow.id }, data: { sourceSha256: 'd'.repeat(64) } })
    try { await s.snapshot({ workspaceId: world.workspaceId, projectId: world.projectId, projectVersionId: world.versionId }); refusals.push(['ocr', 'served']) }
    catch (error) { refusals.push(['ocr', error?.code ?? String(error)]) }
    await db.v2PerceptionProducerEnvelope.update({ where: { id: ocrRow.id }, data: { sourceSha256: ocrRow.sourceSha256 } })
    const restored = await s.snapshot({ workspaceId: world.workspaceId, projectId: world.projectId, projectVersionId: world.versionId })
    record('adversarial-envelope-source-refused', 'an envelope row bound to other source bytes is refused at read with PERSISTENCE_CONFLICT (never served), and the unchanged rows read again',
      refusals.length === 2 && refusals.every(([, code]) => code === 'PERSISTENCE_CONFLICT') && restored.snapshot.rejected.length === 0, { refusals })

    // R5 replay: repeated and fresh-connection reads are the same snapshot
    const reads = []
    for (let index = 0; index < 3; index += 1) reads.push(await s.snapshot({ workspaceId: world.workspaceId, projectId: world.projectId, projectVersionId: world.versionId }))
    const fresh = new PrismaClient()
    let freshRead
    try {
      const freshServices = services(fresh, ctx)
      freshRead = await freshServices.snapshot({ workspaceId: world.workspaceId, projectId: world.projectId, projectVersionId: world.versionId })
    } finally { await fresh.$disconnect() }
    const rows = await db.v2ServerPerceptionSnapshot.count({ where: { workspaceId: world.workspaceId, projectVersionId: world.versionId } })
    record('replay-same-snapshot-hash', 'repeated reads and a fresh connection return the same snapshot hash and the same content-addressed row',
      new Set([...reads, freshRead].map((item) => item.snapshot.snapshotHash)).size === 1 && new Set([...reads, freshRead].map((item) => item.id)).size === 1 && rows === 1,
      { hashes: [...reads, freshRead].map((item) => item.snapshot.snapshotHash), rowsForVersion: rows})
    void actor
  }

  // R3 reorder (PTS): a gapped-PTS source is refused by both producers, no envelope is written, the snapshot says no producer ran
  const gapReport = mainReports.find((report) => report.id === 'robustness-pts-gap-a')
  if (gapReport) {
    const world = producedByClip.get('robustness-pts-gap-a').world
    const ocrRows = await db.v2PerceptionProducerEnvelope.count({ where: { workspaceId: world.workspaceId } })
    const temporalRows = await db.v2TemporalProducerEnvelope.count({ where: { workspaceId: world.workspaceId } })
    const coverage = Object.fromEntries(gapReport.coverage.map((item) => [item.kind, item]))
    record('non-cfr-pts-refused', 'a source with a PTS gap (non-CFR) is refused by both producers: operations fail, no envelope row, the snapshot lists no OCR/temporal input and says NO_PRODUCER_RUN',
      !gapReport.producers.ocr && !gapReport.producers.temporal && gapReport.operations.ocr.operationStatus === 'failed' && gapReport.operations.temporal.operationStatus === 'failed' &&
        ocrRows === 0 && temporalRows === 0 && !gapReport.inputs.some((input) => input.kind === 'ocr' || input.kind === 'temporal') &&
        coverage.ocr.state === 'absent' && coverage.shot.state === 'absent' && coverage.ocr.reasonCode === 'NO_PRODUCER_RUN' && coverage.shot.reasonCode === 'NO_PRODUCER_RUN',
      { operations: { ocr: gapReport.operations.ocr, temporal: gapReport.operations.temporal }, envelopeRows: { ocr: ocrRows, temporal: temporalRows }, coverage: gapReport.coverage })
  }

  // R4 adversarial source (ii): the file at the artifact key is not the file whose SHA-256 the rights/manifest name
  const victim = entries.find((entry) => entry.id === 'static-a')
  const intruder = entries.find((entry) => entry.id !== 'static-a' && entry.spec.frames === 120) ?? entries.find((entry) => entry.id !== 'static-a')
  if (victim && intruder) {
    const world = await seedPerceptionProducerContext(db, { durationFrames: victim.spec.frames, sourceSha256: victim.sha256, byteSize: BigInt(victim.bytes) })
    const destination = join(ctx.artifactRoot, world.artifactKey)
    await mkdir(dirname(destination), { recursive: true })
    await copyFile(join(ctx.corpusDir, intruder.file), destination)
    const s = services(db, ctx)
    const ask = { workspaceId: world.workspaceId, projectId: world.projectId, projectVersionId: world.versionId, sourceArtifactId: world.sourceId, actor: actorFor(world) }
    const ocrQueued = await s.enqueueOcr({ ...ask, sampleIntervalFrames: OCR_SAMPLE_INTERVAL_FRAMES, idempotencyKey: `w63b-adv-ocr-${world.suffix}` })
    const ocrRun = await s.runOcr(`w63b-adv-ocr-worker-${world.suffix}`)
    const temporalQueued = await s.enqueueTemporal({ ...ask, idempotencyKey: `w63b-adv-temporal-${world.suffix}` })
    const temporalRun = await s.runTemporal(`w63b-adv-temporal-worker-${world.suffix}`)
    const ocrOperation = await s.operations.findById(world.workspaceId, ocrQueued.operation.id)
    const temporalOperation = await s.operations.findById(world.workspaceId, temporalQueued.operation.id)
    const rows = (await db.v2PerceptionProducerEnvelope.count({ where: { workspaceId: world.workspaceId } })) + (await db.v2TemporalProducerEnvelope.count({ where: { workspaceId: world.workspaceId } }))
    record('adversarial-source-bytes-refused', 'a source whose bytes differ from the declared SHA-256 is refused by the materializer/producers: both operations fail, no envelope is written',
      ocrRun?.status === 'attempt-failed' && temporalRun?.status === 'attempt-failed' && ocrOperation.operation.status === 'failed' && temporalOperation.operation.status === 'failed' && rows === 0,
      { ocrRun: ocrRun?.status, temporalRun: temporalRun?.status, ocrError: ocrOperation.operation.error ?? null, temporalError: temporalOperation.operation.error ?? null, envelopeRows: rows })
  }
  return results
}

// ------------------------------------------------------------------------------------------------------------ main

async function main() {
  const split = argument('split')
  const corpusDir = argument('corpus')
  const outDir = argument('out')
  const only = argument('only')?.split(',')
  const phase = argument('phase', 'all')
  if (!['development', 'evaluation'].includes(split) || !corpusDir || !outDir) throw new Error('usage: --split <development|evaluation> --corpus <dir> --out <dir>')
  const manifestBytes = await readFile(join(corpusDir, 'manifest.json'))
  const manifest = JSON.parse(manifestBytes.toString('utf8'))
  if (manifest.split !== split) throw new Error(`manifest is for ${manifest.split}`)
  const skipFreeze = process.argv.includes('--no-freeze-check')
  if (skipFreeze && split === 'evaluation') throw new Error('the evaluation split is never run without the freeze check')
  const frozen = await checkFreeze(split, corpusDir, manifestBytes)
  if (frozen.problems.length && !skipFreeze) throw new Error(`freeze check failed:\n${frozen.problems.join('\n')}`)
  const entries = manifest.clips.filter((entry) => !only || only.includes(entry.id) || (phase !== 'main' && ['static-a', 'robustness-pts-gap-a'].includes(entry.id)))
  for (const entry of entries) if (await fileSha(join(corpusDir, entry.file)) !== entry.sha256) throw new Error(`${entry.file} differs from its manifest SHA-256`)
  await mkdir(outDir, { recursive: true })

  const artifactRoot = await mkdtemp(join(tmpdir(), 'w63b-artifacts-'))
  const env = {
    ...process.env, APOLLO_V2_ARTIFACT_ROOT: artifactRoot, APOLLO_V2_ARTIFACT_STORAGE_DRIVER: 'local',
    APOLLO_V2_OCR_FFMPEG_BIN: process.env.APOLLO_OCR_FFMPEG, APOLLO_V2_OCR_FFPROBE_BIN: process.env.APOLLO_OCR_FFPROBE,
    APOLLO_V2_OCR_TESSERACT_BIN: process.env.APOLLO_OCR_TESSERACT, APOLLO_V2_OCR_TESSDATA_DIR: process.env.APOLLO_OCR_TESSDATA,
    APOLLO_V2_OCR_TESSDATA_LICENSE: join(process.env.APOLLO_OCR_TESSDATA ?? '', 'LICENSE'), APOLLO_V2_OCR_LANGUAGES: 'por,eng',
    APOLLO_V2_TEMPORAL_FFMPEG_BIN: process.env.APOLLO_TEMPORAL_FFMPEG, APOLLO_V2_TEMPORAL_FFPROBE_BIN: process.env.APOLLO_TEMPORAL_FFPROBE,
    APOLLO_V2_TEMPORAL_FFMPEG_SHA256: process.env.APOLLO_TEMPORAL_FFMPEG ? await fileSha(process.env.APOLLO_TEMPORAL_FFMPEG) : '',
    APOLLO_V2_TEMPORAL_FFPROBE_SHA256: process.env.APOLLO_TEMPORAL_FFPROBE ? await fileSha(process.env.APOLLO_TEMPORAL_FFPROBE) : '',
  }
  for (const [key, value] of Object.entries(env)) if (key.startsWith('APOLLO_V2_') && value !== undefined) process.env[key] = value
  const ctx = { corpusDir, artifactRoot, runOcr: createPerceptionProducerWorker(env), runTemporal: createTemporalProducerWorker(env) }
  const tesseractVersion = (await exec(env.APOLLO_V2_OCR_TESSERACT_BIN, ['--version'], { windowsHide: true })).stdout.split(/\r?\n/)[0]
  const db = new PrismaClient()
  const reports = []
  const producedByClip = new Map()
  const runId = process.env.APOLLO_S2D_RUN_ID ?? `local-${randomUUID().slice(0, 8)}`
  const startedAt = new Date().toISOString()
  let robustnessResults = []
  try {
    for (const entry of entries) {
      if (phase === 'robustness' && !['static-a', 'robustness-pts-gap-a'].includes(entry.id)) continue
      const started = Date.now()
      const world = await prepareWorld(db, ctx, entry)
      const produced = await produce(db, ctx, entry, world)
      let snapshot = null
      try { snapshot = await produced.services.snapshot({ workspaceId: world.workspaceId, projectId: world.projectId, projectVersionId: world.versionId }) }
      catch (error) { produced.snapshotError = { code: error?.code ?? null, message: String(error?.message ?? error).slice(0, 500) } }
      const report = summarize(entry, produced, snapshot)
      if (produced.snapshotError) report.snapshotError = produced.snapshotError
      reports.push(report)
      producedByClip.set(entry.id, { produced, world })
      await mkdir(join(outDir, 'clips'), { recursive: true })
      await writeFile(join(outDir, 'clips', `${entry.id}.json`), stable({ report, observations: snapshot?.result.observations ?? [], coverage: snapshot?.result.coverage ?? [] }))
      console.log(JSON.stringify({ event: 'clip', id: entry.id, seconds: Number(((Date.now() - started) / 1000).toFixed(1)), ocr: produced.outcome.ocr.status, temporal: produced.outcome.temporal.status,
        snapshotHash: report.snapshotHash }))
    }
    if (phase !== 'main') robustnessResults = await robustness(db, ctx, reports, producedByClip, entries)
  } finally {
    await db.$disconnect().catch(() => undefined)
    await disconnectV2PostgresClient().catch(() => undefined)
    await rm(artifactRoot, { recursive: true, force: true })
  }
  const strata = phase === 'robustness' ? {} : aggregateStrata(reports.filter((report) => report.stratum !== 'robustness-pts-gap'))
  const summary = {
    schemaVersion: 'w63b-results/v1', split, runId, startedAt, finishedAt: new Date().toISOString(), phase,
    head: await git('rev-parse', 'HEAD'), freezeCommit: frozen.freezeCommit, freezeProblemsIgnored: skipFreeze ? frozen.problems : [],
    manifestSha256: frozen.manifestSha, preregVersion: frozen.freeze.preregVersion, frozenFiles: frozen.freeze.files,
    tools: { ffmpegSha256: manifest.toolchain.ffmpegSha256, tesseract: tesseractVersion, tesseractExe: process.env.APOLLO_OCR_TESSERACT ? await fileSha(process.env.APOLLO_OCR_TESSERACT) : null,
      ocrFfmpegSha256: process.env.APOLLO_OCR_FFMPEG ? await fileSha(process.env.APOLLO_OCR_FFMPEG) : null, ffprobeSha256: process.env.APOLLO_OCR_FFPROBE ? await fileSha(process.env.APOLLO_OCR_FFPROBE) : null, node: process.version },
    unrun: manifest.unrun, strata, robustness: robustnessResults,
    clips: reports.map((report) => ({ id: report.id, stratum: report.stratum, snapshotHash: report.snapshotHash, ocr: report.operations.ocr?.status, temporal: report.operations.temporal?.status })),
  }
  await writeFile(join(outDir, 'results.json'), stable(summary))
  const verdicts = Object.fromEntries(Object.entries(strata).map(([id, item]) => [id, item.verdict]))
  console.log(JSON.stringify({ event: 'summary', runId, verdicts, robustness: robustnessResults.map((item) => [item.id, item.pass]) }))
}

main().catch((error) => { console.error(error.stack ?? error); process.exit(1) })
